        "text": "**Textilreinigung & Wäscheservice Glanzfein**\nRheinstraße 19 · 65185 Wiesbaden · Telefon: 0611 / 78 99 10\n\nSchonende Pflege für Ihre feinsten Textilien – seit über 25 Jahren Ihr verlässlicher Meisterbetrieb in Wiesbaden.\n\n**Unsere Preise im Überblick:**\n• Herrenhemd / Damenbluse (gewaschen & handgebügelt): **2,80 Euro**\n• Sakko / Blazer: **9,50 Euro**\n• Anzughose / Rock: **7,00 Euro**\n• Kompletter 2-Teiler Anzug oder Kostüm: **15,50 Euro**\n• Wintermantel / Daunenjacke (inklusive Imprägnierung): **19,00 Euro**\n• Bettwäsche-Set (1 Kissen- + 1 Deckenbezug): **8,50 Euro**\n\n**Bearbeitungszeit:**\nNormalerweise ist Ihre Kleidung innerhalb von **48 Stunden (zwei Werktagen)** frisch gereinigt und abholbereit. Benötigen Sie Ihre Kleidung noch am selben Tag? Für unseren **Express-Service** bis 17:00 Uhr (Abgabe bis spätestens 9:00 Uhr morgens) berechnen wir einen Aufschlag von **50 %**.\n\n**Bequemer Hol- und Bringservice:**\nFür Firmenkunden und Privathaushalte bieten wir einen praktischen Abholservice an. Ab einem Auftragswert von **35,- Euro** holen wir Ihre Textilien direkt an Ihrer Haustür ab und bringen sie innerhalb von drei Tagen gebügelt zurück (Umkreis 10 km, darunter 5,- Euro Fahrtpauschale).\n\nÖffnungszeiten: Mo–Fr 7:30–18:30 Uhr, Sa 8:30–13:00 Uhr.",
