        "text": "**Möbelhaus SkandiHome Nord**\nCarl-Zeiss-Straße 15 · 24145 Kiel · www.skandihome-kiel.de\n\nLiebe Kundinnen und Kunden,\n\nvielen Dank für Ihren Möbeleinkauf bei SkandiHome! Hier finden Sie alle wichtigen Informationen zur Lieferung und zum Aufbauservice Ihrer neuen Einrichtungsgegenstände.\n\n**Lieferung direkt in Ihre Wohnung:**\n• **Standardlieferung (bis hinter die erste verschließbare Wohnungstür):** Für Großmöbel (Sofas, Betten, Schränke) berechnen wir eine Pauschale von **49,- Euro** innerhalb von Kiel und einem Umkreis von 20 Kilometern. Ab einem Einkaufswert von **1.000,- Euro** liefern wir Ihre Möbel **völlig kostenlos**!\n• **Lieferzeit:** Auf Lager befindliche Ware liefern wir innerhalb von 5 bis 7 Werktagen. Unsere Spedition kontaktiert Sie mindestens zwei Tage vor der Anlieferung per SMS, um ein 2-stündiges Lieferzeitfenster (z. B. 10:00–12:00 Uhr) abzustimmen.\n\n**Zusatzservices auf Wunsch:**\n1. **Fachgerechter Aufbauservice:** Gerne montieren unsere erfahrenen Schreiner Ihre Möbel direkt vor Ort. Die Kosten betragen 15 % des Möbelkaufpreises (Mindestmontagegebühr: 60,- Euro).\n2. **Mitnahme von Altmöbeln:** Gerne nehmen wir Ihr altes Sofa oder Bett bei Neuanlieferung gleich mit und entsorgen es umweltgerecht (Festpreis: 35,- Euro pro Möbelstück).\n\nBei Rückfragen zu Ihrer Bestellung wenden Sie sich bitte mit Ihrer Auftragsnummer an service@skandihome-kiel.de.",
