        "text": "**Handwerksbäckerei & Konditorei Sonnenbrot**\nBäckerstraße 4 · 30159 Hannover · www.sonnenbrot-hannover.de\n\nSeit 1954 backen wir täglich mit Leidenschaft nach traditionellen Rezepten, ohne künstliche Konservierungsstoffe und mit Getreide aus regionalem Bio-Anbau.\n\n**Individuelle Festtagstorten für jeden Anlass:**\nOb Geburtstag, Hochzeit, Taufe oder Firmenjubiläum – unsere Konditormeister gestalten Ihre Traumtorte ganz nach Ihren persönlichen Wünschen!\n• **Beliebte Füllungen:** Schwarzwälder Kirsch, Himbeer-Joghurt, Schoko-Mousse, Mango-Maracuja oder klassische Frankfurter Kranz-Buttercreme.\n• **Individuelle Dekoration:** Echte Blüten, handmodellierte Marzipanfiguren oder essbarer Fotodruck mit Ihrem Lieblingsbild.\n• **Allergikerfreundlich:** Auf Wunsch backen wir laktosefreie, vegane oder glutenfreie Tortenböden.\n\n**Bestellfristen & Abholung:**\n• Standardtorten aus unserem Katalog: Bitte mindestens **3 Werktage im Voraus** bestellen.\n• Mehrstöckige Hochzeitstorten und Fototorten: Mindestens **10 Tage im Voraus** bestellen.\n• Abholzeiten: Dienstag bis Samstag von 8:00 bis 17:30 Uhr, sonntags von 8:00 bis 11:30 Uhr.\n• Lieferdienst: Innerhalb des Stadtgebiets Hannover liefern wir gekühlte Festtagstorten samstags und sonntags gegen 15,- Euro Liefergebühr direkt zu Ihrer Feier.\n\nBesuchen Sie uns für eine persönliche Geschmacksberatung jeden Mittwochnachmittag zwischen 14:00 und 17:00 Uhr!",
        "textEN": "Craft Bakery & Confectionery Sonnenbrot\nBäckerstraße 4 · 30159 Hanover\n\nCustom celebration cakes: Black forest, raspberry yogurt, chocolate mousse, mango passionfruit, buttercream. Edible photo prints, sugar flowers, marzipan. Allergy-friendly: lactose-free, vegan, gluten-free options on request.\nOrder deadlines: Standard cakes at least 3 workdays in advance; multi-tiered wedding/photo cakes at least 10 days in advance.\nPickups: Tue-Sat 8:00-17:30, Sun 8:00-11:30. Delivery within Hanover: €15 refrigerated weekend delivery.",
