        "text": "**Gärtnerei & Blumenhaus Rosenrot**\nBlumenweg 12 · 01067 Dresden · Inhaberin: Claudia Wagner\n\nBringen Sie Farbe und Duft in Ihr Zuhause! Rechtzeitig zum Frühlingsanfang erwarten Sie in unseren Gewächshäusern über 200 Sorten blühende Frühlingsboten.\n\n**Unsere aktuellen Frühjahrs-Angebote:**\n• **Balkonpflanzen-Aktion:** Kaufen Sie 10 Balkonpflanzen (z. B. Geranien, Petunien, Verbenen) und erhalten Sie einen **20-Liter-Sack Qualitäts-Pflanzerde gratis** dazu!\n• **Kostenloser Eintopf-Service:** Bringen Sie Ihre leeren Balkonkästen oder Töpfe zu uns. Sie suchen die Pflanzen und Erde bei uns aus, und unsere Gärtner pflanzen alles fachgerecht für Sie ein – der Arbeitsaufwand ist für Sie völlig kostenlos!\n• **Frische Blumensträuße:** Täglich frisch gebundene Frühlingssträuße mit Tulpen, Ranunkeln und Freesien ab **12,- Euro**.\n\n**Lieferservice für schwere Pflanzkübel & Erde:**\nKein Platz im Auto? Wir liefern schwere Blumenerde, Bäumchen und große Kübel im Stadtgebiet Dresden dienstags und freitags für nur **8,- Euro Lieferpauschale** direkt bis auf Ihren Balkon oder in Ihren Garten.\n\nÖffnungszeiten: Montag bis Freitag 8:30 – 18:00 Uhr, Samstag 8:30 – 14:00 Uhr, Sonntag 10:00 – 12:00 Uhr (Verkauf von Schnittblumen).",
