        "text": "**Stadtbibliothek Leselust – Zentralbibliothek**\nKulturplatz 3 · 44137 Dortmund · Telefon: 0231 / 50 22 10\n\nLiebe Leserinnen und Leser, liebe Familien,\n\nherzlich willkommen in Ihrer Stadtbibliothek! Bei uns stehen Ihnen über 80.000 Medien zur Verfügung: Bestseller, Sprachkurse, Hörbücher, Graphic Novels, Videospiele und Brettspiele.\n\n**Sommerferien-Leseclub für Schüler (6 bis 16 Jahre):**\n• Zeitraum: Vom **15. Juli bis zum 30. August**.\n• Wie funktioniert es? Lies mindestens drei Club-Bücher während der Ferien, bewerte sie kurz auf deiner Lesekarte und nimm an unserer großen Abschlussfeier mit Tombola und tollen Buchpreisen am **6. September** teil! Die Club-Teilnahme ist völlig kostenlos.\n\n**Digitale Bibliothek (Onleihe & Filmstreaming):**\nMit einem gültigen Bibliotheksausweis (Jahresgebühr für Erwachsene: **20,- Euro**, für Kinder und Jugendliche bis 18 Jahre **kostenlos**) nutzen Sie rund um die Uhr unsere digitale Onleihe auf Ihrem Tablet, Smartphone oder E-Reader sowie kostenloses Filmstreaming auf filmfriend.de.\n\n**Verlängerungen & Rückgabe:**\nSie können entliehene Bücher bis zu zweimal online in Ihrem Benutzerkonto verlängern, sofern keine Vormerkung anderer Leser vorliegt. Außerhalb der Öffnungszeiten steht Ihnen unser 24-Stunden-Rückgabeautomat am Seiteneingang zur Verfügung.\n\nÖffnungszeiten: Dienstag bis Freitag 10:00 – 19:00 Uhr, Samstag 10:00 – 15:00 Uhr. Montags geschlossen.",
        "textEN": "City Library Leselust – Central Library\nKulturplatz 3 · 44137 Dortmund\n\nSummer reading club for students (ages 6 to 16): July 15th to August 30th. Read at least 3 books, rate them on card, attend closing party on Sept 6th with raffle prizes! Free participation.\nDigital library (Onleihe & Streaming): Annual fee for adults €20, children/youth under 18 free. 24/7 access to e-books and streaming.\nRenewals: up to 2 times online if no reservations. 24/7 return machine at side entrance.\nOpening hours: Tue-Fri 10:00–19:00, Sat 10:00–15:00, Mon closed.",
