        "text": "**Volkshochschule Landkreis Mitte**\nWilhelmstraße 24 · 35390 Gießen · E-Mail: anmeldung@vhs-mitte.de\n\nDas neue Herbst-/Wintersemester beginnt am **7. Oktober**! Entdecken Sie über 400 interessante Kurse in den Bereichen Sprachen, Gesundheit, Beruf und Kultur.\n\n**Ausgewählte Sprachkurse am Abend:**\n1. **Deutsch A2.1 – Kompaktkurs am Abend (Kurs-Nr. DE-201):**\n   Montag und Mittwoch, 18:30 – 20:00 Uhr (12 Wochen, insgesamt 48 Unterrichtsstunden). Lehrbuch: „Schritte Plus Neu A2“. Kursgebühr: **145,- Euro** (Ermäßigung für Studierende und Arbeitssuchende: 20 %).\n2. **Spanisch für Anfänger ohne Vorkenntnisse (Kurs-Nr. SP-101):**\n   Donnerstags, 19:00 – 20:30 Uhr (10 Abende). Schwerpunkt auf Urlaubssituationen, Restaurantbesuche und Hotelreservierungen. Kursgebühr: **85,- Euro**.\n3. **Italienische Küche & Konversation (Kurs-Nr. IT-305):**\n   Freitag, 15. November, 17:30 – 21:30 Uhr. Kochen traditioneller Pasta mit einer Muttersprachlerin. Kursgebühr: **42,- Euro** (inkl. 18,- Euro Lebensmittelumlage).\n\n**Kostenlose Einstufungsberatung:**\nSie sind unsicher, welches Sprachniveau zu Ihnen passt? Kommen Sie zu unserem offenen Einstufungstag am **Samstag, 28. September, von 10:00 bis 14:00 Uhr** (Raum 104, ohne Voranmeldung).\n\nAnmeldeschluss für alle Semesterkurse ist der **2. Oktober**.",
