        "text": "**Stadtverwaltung Bürgeramt Mitte**\nRathausplatz 1 · 68159 Mannheim · www.mannheim.de/buergeramt\n\nLiebe Bürgerinnen und Bürger,\n\num lange Wartezeiten zu vermeiden, arbeitet das Bürgeramt Mitte **ausschließlich mit vorheriger Terminvereinbarung**.\n\n**Wichtige Hinweise zur Anmeldung einer Wohnung:**\n• Nach dem Bundesmeldegesetz müssen Sie Ihren neuen Wohnsitz innerhalb von **zwei Wochen nach dem Einzug** anmelden.\n• **Erforderliche Unterlagen:**\n  1. Gültiger Personalausweis oder Reisepass aller anzumeldenden Personen\n  2. Ausgefüllte und vom Vermieter unterschriebene **Wohnungsgeberbestätigung** (der Mietvertrag reicht gesetzlich nicht aus!)\n  3. Bei Kindern: Geburtsurkunde im Original.\n• Die Anmeldung des Wohnsitzes ist **gebührenfrei**.\n\n**Beantragung von Personalausweis & Reisepass:**\n• Für Personalausweis (Gebühr ab 24 Jahren: **37,- Euro**) und Reisepass (**70,- Euro**) bringen Sie bitte ein aktuelles biometrisches Passfoto mit (nicht älter als 6 Monate). Vor Ort steht auch ein digitaler Fotoautomat für 6,- Euro zur Verfügung.\n• Bearbeitungszeit: Der Personalausweis dauert ca. 2 bis 3 Wochen, der Reisepass 4 bis 5 Wochen.\n\n**Zahlungshinweis:**\nAm Schalter akzeptieren wir ausschließlich bargeldlose Zahlung (EC-Karte, Girocard, Debit- oder Kreditkarte). Barzahlung ist nicht möglich!\n\nTermine buchen Sie online unter www.mannheim.de/termin oder telefonisch über die Behördennummer 115.",
        "textEN": "Citizen's Office Mitte\nRathausplatz 1 · 68159 Mannheim\n\nAll services strictly by prior appointment! Address registration:\n• Must register within 2 weeks of moving in.\n• Required docs: Valid ID/passport; completed and landlord-signed Wohnungsgeberbestätigung (rental contract is legally NOT sufficient!); original birth certificate for kids.\n• Registration is free of charge.\nID card & passport: ID card €37 (adults 24+), passport €70. Bring biometric photo (< 6 months) or use booth on site (€6). Turnaround: ID card 2-3 weeks, passport 4-5 weeks.\nPayment note: strictly cashless at counter (EC/debit/credit card). No cash accepted!",
