        "text": "**Schwarzwaldverein Ortsgruppe Titisee**\nPostfach 1120 · 79822 Titisee-Neustadt · www.schwarzwaldverein-titisee.de\n\n**Einladung zur gemeinsamen Herbstwanderung: Über den Feldbergsteig zur Zastler Hütte**\n\nLiebe Wanderfreunde und Gäste,\n\nwenn sich die Buchenwälder im Hochschwarzwald golden färben, ist die schönste Wanderzeit gekommen! Begleiten Sie unsere zertifizierten Wanderführer auf einer abwechslungsreichen Panoramatour.\n\n**Tourdaten im Überblick:**\n• **Datum & Uhrzeit:** Sonntag, 13. Oktober, Treffpunkt um **9:15 Uhr** am Bahnhof Titisee (Weiterfahrt mit Bus 7300 zum Feldberger Hof).\n• **Streckenlänge:** ca. 12,5 Kilometer, Höhenunterschied: ca. 380 Meter im Auf- und Abstieg.\n• **Schwierigkeit:** Mittelschwer (gute Grundkondition und Trittsicherheit erforderlich, Gehzeit ca. 4 bis 4,5 Stunden).\n• **Ausrüstung:** Knöchelhohe Wanderschuhe mit gutem Profil, wetterfeste Kleidung (Zwiebellook), ausreichend Trinkwasser und kleine Rucksackverpflegung.\n\n**Einkehr:**\nGegen 13:00 Uhr kehren wir für 1,5 Stunden in der urigen **Zastler Hütte** ein (warme Schwarzwälder Spezialitäten, Vesperbretter, hausgemachter Apfelstrudel). Die Kosten für Speisen und Getränke trägt jeder Teilnehmer selbst.\n\n**Kosten:**\nDie Teilnahme an der Wanderung ist für Mitglieder des Schwarzwaldvereins kostenlos, Gäste zahlen einen Unkostenbeitrag von **5,- Euro** vor Ort beim Wanderleiter.\n\nAnmeldung erbeten bis Freitag, 11. Oktober, per Mail an wandern@schwarzwaldverein-titisee.de.",
        "textEN": "Black Forest Club Titisee\nAutumn hike over the Feldbergsteig to Zastler Hütte.\nTour details: Sunday, October 13th, meeting at 9:15 AM at Titisee railway station (bus 7300 to start).\nRoute: approx 12.5 km, 380m elevation gain/loss. Moderate difficulty (good fitness and sure-footedness required, walking time 4-4.5 hours).\nGear: ankle-high boots with grip, layered weather clothes, water, trail snacks.\nHut stop: around 1:00 PM at Zastler Hütte for 1.5 hours (hot specialties, apple strudel; pay own meals).\nCosts: Free for club members, guests pay €5 contribution to guide.\nRegister by Friday, Oct 11th.",
