        "text": "**Repair-Café Altstadt – Hilfe zur Selbsthilfe**\nBürgerzentrum Alte Schule · Schulstraße 8 · 53111 Bonn\n\nIst Ihr Toaster kaputt, die Kaffeemaschine streikt, der Reißverschluss der Lieblingsjacke klemmt oder das Holzstühlchen wackelt? Werfen Sie geliebte Gegenstände nicht gleich in den Müll!\n\nJeden **zweiten Samstag im Monat von 14:00 bis 17:30 Uhr** öffnen wir unsere Türen für alle Bürgerinnen und Bürger.\n\n**So funktioniert das Repair-Café:**\n• Gemeinsam mit unseren fachkundigen ehrenamtlichen Experten (Elektriker, Näherinnen, Tischler und Fahrradmechaniker) untersuchen und reparieren Sie Ihren defekten Gegenstand.\n• **Was kann mitgebracht werden?**\n  Alles, was Sie selbst tragen können: Kleine Elektrogeräte (Föhn, Mixer, Radios), Kleidung zum Flicken, Holzspielzeug und mechanische Uhren. *Hinweis: Große Haushaltsgeräte wie Waschmaschinen oder Kühlschränke können nicht angenommen werden.*\n• **Ersatzteile:** Spezialteile (z. B. passende Akkus, Netzkabel oder Schalter) müssen von den Besuchern selbst besorgt und mitgebracht werden.\n• **Kosten:** Die Reparaturhilfe ist grundsätzlich **kostenlos**. Da wir uns rein ehrenamtlich organisieren, freuen wir uns über eine freiwillige Spende in unsere Kaffeedose zur Deckung von Werkzeugkosten.\n\nWährend eventueller Wartezeiten gibt es frischen Fairtrade-Kaffee, Tee und selbstgebackene Kuchen im Café-Bereich.\n\nNächster Termin: Samstag, 12. Oktober ab 14:00 Uhr!",
        "textEN": "Repair Café Altstadt\nBürgerzentrum Alte Schule · Schulstraße 8 · 53111 Bonn\n\nEvery second Saturday of the month from 2:00 PM to 5:30 PM. How it works: Together with volunteer experts (electricians, seamstresses, carpenters, bike mechanics) you examine and fix your item. What to bring: Anything you can carry yourself: small electronics (hairdryer, mixer, radio), clothes to patch, wooden toys. Note: large appliances like washing machines or fridges cannot be accepted. Spare parts: special parts must be brought by visitors. Costs: free of charge, voluntary donations welcome. Tea and cake available. Next date: Saturday, Oct 12th at 2 PM.",
